/ {
	soc {
		#address-cells = <1>;
		#size-cells = <1>;

		test_device@0 {
			compatible = "test-device";
			reg = <0x40000000 0x100>; /* Fix: Added size 0x100 to the reg property */
			pinctrl-0 = <&pinctrl_test_device_default>;
			status = "okay";
		};
	};

	pinctrl_test_device_default: pinctrl_test_device_default {
		group0 {
			pinmux = <Z_PINCTRL_DT_PIN(DT_NODELABEL(gpio0), 0, A)>;
		};
		group1 {
			pinmux = <Z_PINCTRL_DT_PIN(DT_NODELABEL(gpio0), 1, B)>;
		};
	};
};
